"use client"

import { Switch as SwitchPrimitive } from "@base-ui/react/switch"

import { cn } from "@/lib/utils"

// Control Room Switch: breaker toggle.
// Off: recessed dark track. On: the track adopts the primary Button's
// signal-green plate (rim + highlight + glow, scaled down). The thumb is a
// near-black slug so the energized track reads as the lit element.

// Base UI className can be a state function; the wrapper feeds it to cn(), so
// narrow it to a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string }

function Switch({
  className,
  ...props
}: WithClassName<SwitchPrimitive.Root.Props>) {
  return (
    <SwitchPrimitive.Root
      className={cn(
        "group/switch peer inline-flex h-5 w-9 shrink-0 cursor-pointer items-center rounded-sm",
        "border border-border bg-input",
        "[box-shadow:var(--shadow-inset)]",
        "transition-all duration-fast",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/60 focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        "data-disabled:cursor-not-allowed data-disabled:opacity-40",
        "data-checked:border-transparent data-checked:bg-primary",
        "data-checked:[box-shadow:var(--shadow-control)]",
        className
      )}
      {...props}
    >
      <SwitchPrimitive.Thumb
        className={cn(
          "pointer-events-none block size-3.5 rounded-xs",
          "bg-muted-foreground shadow-[0_0.0625rem_0.125rem_oklch(0_0_0/0.5)]",
          "data-unchecked:translate-x-0.5",
          "data-checked:translate-x-[1.125rem] data-checked:bg-primary-foreground",
          "origin-left data-checked:origin-right rtl:origin-right rtl:data-checked:origin-left transition-[translate,scale,transform-origin,background-color,box-shadow] duration-[260ms,140ms,0ms,150ms,150ms] delay-[0ms,0ms,140ms,0ms,0ms] ease-out motion-safe:group-active/switch:scale-x-[1.18] motion-reduce:transition-none"
        )}
      />
    </SwitchPrimitive.Root>
  )
}
Switch.displayName = "Switch"

export { Switch }
